<script setup lang="ts">
import {computed} from 'vue'
import {fieldLabel} from './types'
type Definition={id:string;label:string;type?:string;group?:string;width?:string;minHeight?:number;panelTheme?:string;panelTitle?:string}
const props=defineProps<{fields?:Definition[];values:Record<string,unknown>;theme?:string;title?:string}>()
const items=computed(()=>Object.entries(props.values).map(([id,value])=>({id,value,definition:props.fields?.find(f=>f.id===id)})))
function display(value:unknown){return value==null||value===''?'未知':typeof value==='boolean'?value?'是':'否':String(value)}
</script>
<template><section class="state-panel" :class="'state-theme-'+(theme||fields?.[0]?.panelTheme||'paper')" :aria-label="title||fields?.[0]?.panelTitle||'人物状态'"><h3 v-if="title||fields?.[0]?.panelTitle">{{title||fields?.[0]?.panelTitle}}</h3><div class="world-fields state-field-grid"><template v-for="(item,i) in items" :key="item.id"><h4 v-if="item.definition?.group&&item.definition.group!==items[i-1]?.definition?.group" class="state-group">{{item.definition.group}}</h4><div class="state-field" :class="{half:item.definition?.width==='half'}" :style="{minHeight:(item.definition?.minHeight||44)+'px'}"><span>{{fieldLabel(fields,item.id)}}</span><img v-if="item.definition?.type==='image'&&typeof item.value==='string'&&/^data:image\/(png|jpeg|webp);base64,/.test(item.value)" :src="item.value" :alt="fieldLabel(fields,item.id)"><ul v-else-if="Array.isArray(item.value)&&item.value.length"><li v-for="(line,index) in item.value" :key="index">{{line}}</li></ul><strong v-else>{{Array.isArray(item.value)?'暂无条目':display(item.value)}}</strong></div></template></div></section></template>
<style scoped>.state-panel{padding:8px 0;color:var(--ink,#252923);min-width:0}.state-panel h3,.state-group{margin:8px 0}.state-field-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.state-field{display:flex;flex-direction:column;gap:4px;grid-column:span 2;min-width:0;overflow-wrap:anywhere}.state-field.half{grid-column:span 1}.state-field>span{font-size:12px;opacity:.8}.state-field ul{margin:0;padding-left:20px}.state-group{grid-column:span 2}.state-field img{max-width:120px;max-height:120px;border-radius:8px;object-fit:contain}.state-theme-scroll{background:#f4e9d1;padding:16px;border:1px solid #c9ab75;border-radius:10px;color:#463820}.state-theme-terminal{background:#17241c;padding:16px;border-radius:10px;color:#d5efda;font-family:monospace}.state-theme-soft{background:#edf1f6;padding:16px;border-radius:16px;color:#25374b}@media(max-width:600px){.state-field.half{grid-column:span 2}}</style>
